<script>
(() => {
  const API = location.pathname.replace(/\/$/, '') + '/api';
  // Signed session issued by the (Basic-auth protected) page request - see src/session.js.
  const SESSION = '__RFE_SESSION__';
  const DEMO = new URLSearchParams(location.search).has('demo');
  const REFRESH_MS = 30000;
  const PAGE = 50;
  const STATUS = { escalated: 'Escalated', in_queue: 'In Queue', ready_to_post: 'Ready to Post', posted: 'Posted', not_posted: 'Not posting', resolved: 'Resolved', logged: 'Logged' };
  const LANE = { ready_to_post: 'Positive', logged: 'Neutral', in_queue: 'Mild negative', escalated: 'Escalated' };
  const state = { status: '', offset: 0, data: null, paused: false, timer: null, charts: {}, openId: null };
  const $ = (s) => document.querySelector(s);
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const css = (v) => getComputedStyle(document.documentElement).getPropertyValue(v).trim();
  const fmtDate = (t) => new Date(t).toLocaleString('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
  const pct = (x) => x == null ? '–' : Math.round(x * 100) + '%';
  // localStorage is unavailable inside n8n's sandboxed pages, so the name also lives in the
  // URL hash (#me=Tom) - bookmark the dashboard after setting it.
  const hashGet = (k) => new URLSearchParams(location.hash.slice(1)).get(k);
  const store = {
    get(k) { try { const v = localStorage.getItem(k); if (v) return v; } catch (e) {} return hashGet('me'); },
    set(k, v) { try { localStorage.setItem(k, v); } catch (e) {} try { history.replaceState(null, '', '#me=' + encodeURIComponent(v)); } catch (e) {} },
  };
  const actor = () => store.get('rfe_actor') || '';

  function toast(msg) { const t = $('#toast'); t.textContent = msg; t.style.display = 'block'; clearTimeout(t._h); t._h = setTimeout(() => (t.style.display = 'none'), 3500); }

  async function api(body) {
    if (DEMO) return demoApi(body);
    const r = await fetch(API, { method: 'POST', headers: { 'content-type': 'application/json', 'x-rfe-session': SESSION }, credentials: 'omit', body: JSON.stringify(body) });
    if (r.status === 401) { state.paused = true; throw new Error('session expired - reload the page'); }
    if (!r.ok) throw new Error('HTTP ' + r.status);
    const j = await r.json();
    return j.result !== undefined ? j.result : j;
  }

  function filters() {
    const b = $('#f-branch').value;
    const to = $('#f-to').value;
    return {
      from: $('#f-from').value || null,
      to: to ? new Date(new Date(to).getTime() + 86400000).toISOString().slice(0, 10) : null,
      branch_ids: b ? [Number(b)] : [], region_id: $('#f-region').value || null,
      min_score: $('#f-min').value, max_score: $('#f-max').value, q: $('#f-q').value,
      statuses: state.status ? [state.status] : [], limit: PAGE, offset: state.offset,
    };
  }

  async function load() {
    try {
      const d = await api({ op: 'data', filters: filters() });
      state.data = d;
      render(d);
      $('#dot').className = 'dot' + (state.paused ? ' paused' : '');
      $('#updated').textContent = 'Updated ' + new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) + (state.paused ? ' · paused' : ' · live');
