      $('#dot').className = 'dot err';
      $('#updated').textContent = 'Could not refresh (' + e.message + ')';
    }
  }
  function schedule() { clearInterval(state.timer); if (!state.paused) state.timer = setInterval(() => { if (!$('#dlg').open) load(); }, REFRESH_MS); }

  function fillSelect(sel, items, keep) {
    const v = sel.value; const first = sel.options[0].outerHTML;
    sel.innerHTML = first + items.map((i) => `<option value="${i.id}">${esc(i.name)}</option>`).join('');
    if (keep) sel.value = v;
  }

  function render(d) {
    if (!$('#f-branch').options[1]) { fillSelect($('#f-branch'), d.branch_list); fillSelect($('#f-region'), d.region_list); }
    const k = d.kpis;
    $('#n-all').textContent = k.responses;
    for (const s of ['escalated', 'in_queue', 'ready_to_post', 'resolved', 'posted']) {
      const map = { escalated: k.escalated_open, in_queue: k.in_queue, ready_to_post: k.ready_to_post, resolved: k.resolved, posted: k.posted };
      $('#n-' + s).textContent = map[s];
    }
    $('#n-logged').textContent = '';
    const tiles = [
      ['Feedback received', k.responses, `${pct(k.response_rate)} of ${k.requests_sent} requests`],
      ['Average score', k.avg_score_100 ?? '–', '0-100, 50 = neutral'],
      ['Escalated - open', k.escalated_open, `${k.overdue_escalations} overdue · ${pct(k.escalation_rate)} of all feedback`],
      ['In Queue', k.in_queue, `${k.drafts_waiting} draft replies waiting`],
      ['Ready to Post', k.ready_to_post, `${k.posted} posted`],
      ['Median time to acknowledge', k.median_ack_minutes == null ? '–' : k.median_ack_minutes + ' min', `${pct(k.ack_within_sla)} within SLA`],
      ['Repeat unhappy customers', k.repeat_customers, 'escalated automatically'],
    ];
    $('#kpis').innerHTML = tiles.map(([a, b, c]) => `<div class="kpi"><div class="k">${esc(a)}</div><div class="v">${esc(b)}</div><div class="s">${esc(c)}</div></div>`).join('');

    const declining = d.branches.filter((b) => b.declining);
    $('#alerts').innerHTML = (declining.length ? `<div class="alert" role="alert"><b>▼ Declining sentiment:</b> ${declining.map((b) => `${esc(b.name)} (${esc(b.declining_reason)})`).join(' · ')}</div>` : '') +
      (k.unmatched_inbound ? `<div class="alert" style="border-left-color:var(--warning)"><b>${k.unmatched_inbound}</b> inbound message(s) from unknown numbers need a look. <button id="see-unmatched">View</button></div>` : '');
    const su = $('#see-unmatched'); if (su) su.onclick = showUnmatched;

    renderFeed(d);
    renderBranches(d.branches);
    $('#cats').querySelector('tbody').innerHTML = d.categories.length
      ? d.categories.map((c) => `<tr><td>${esc(c.cat.replace(/_/g, ' '))}</td><td class="num">${c.n}</td></tr>`).join('')
      : '<tr><td colspan="2" class="muted">No issues in this period.</td></tr>';
    renderCharts(d);
  }

  function nextStep(f) {
    if (f.status === 'escalated') return f.case_status === 'open' ? `<span class="flag">Acknowledge${f.ack_due_at && new Date(f.ack_due_at) < new Date() ? ' (overdue)' : ''}</span>` : (f.draft && f.draft.status === 'draft' ? 'Review draft reply' : 'Resolve');
